using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
using GenesisMesh;
using GenesisMesh.Tests;
using Xunit;

namespace GenesisMesh.Sdk.Tests;

/// <summary>
/// Remediation and reviews (1.9.0): the shared conformance suite <c>remediation</c> (1.4.0), generated by the Python
/// reference and copied here unchanged; remediation records signed as the reference signs them, and refused before
/// signing as the NA would refuse them; and the rules the vectors reach only in part.
/// </summary>
public class RemediationTests
{
    private static readonly string SuitePath = Path.Combine(AppContext.BaseDirectory, "testdata", "conformance", "remediation.json");

    private static readonly HashSet<string> KindsRun = new()
    {
        "policy_canonical", "policy_validation", "remediation_plan", "due_time", "transition", "decision_plan", "rfc3339",
        "emergency_map", "review_request", "canonical_form", "verify_record", "remediation_check", "steps_problem",
        "admin_approval", "review_approval", "review_holders", "verify_export",
    };

    private static readonly HashSet<string> KindsNotRun = new();

    // The zero seed's public key.
    private const string ZeroKey = "O2onvM62pC1io6jQKm8Nc2UyFXcd4kOmOsBIoYtZ2ik=";

    private static JsonElement Suite() => JsonDocument.Parse(File.ReadAllText(SuitePath)).RootElement;

    private static JsonElement Vector(string id) =>
        Suite().GetProperty("vectors").EnumerateArray().Single(v => v.GetProperty("id").GetString() == id);

    public static IEnumerable<object[]> VectorIds() => Suite().GetProperty("vectors").EnumerateArray()
        .Where(v => KindsRun.Contains(v.GetProperty("kind").GetString()!))
        .Select(v => new object[] { v.GetProperty("id").GetString()! });

    internal static ConformanceReceipt Receipt() => ConformanceReceipts.For(
        "remediation", typeof(RemediationTests), nameof(ReproducesTheReferenceOutcome), VectorIds(), KindsRun, KindsNotRun);

    [Fact]
    public void EveryKindIsRunOrListedAsNotRun() => ConformanceReceipts.Record(Receipt());

    [Fact]
    public void IsTheRemediationSuiteOf340Vectors()
    {
        var suite = Suite();
        Assert.Equal("remediation", suite.GetProperty("suite").GetString());
        Assert.Equal("1.4.0", suite.GetProperty("version").GetString());
        Assert.Equal(340, suite.GetProperty("vectors").GetArrayLength());
        Assert.Equal(340, VectorIds().Count());
    }

    private static string? Str(JsonElement o, string name) =>
        o.TryGetProperty(name, out var v) && v.ValueKind == JsonValueKind.String ? v.GetString() : null;

    private static List<BoundaryPolicy> Policies(JsonElement input) => input.GetProperty("policies").Deserialize<List<BoundaryPolicy>>()!;

    private static RemediationDefaults? Defaults(JsonElement input) =>
        input.TryGetProperty("defaults", out var d) && d.ValueKind == JsonValueKind.Object
            ? new RemediationDefaults(d.GetProperty("grace_seconds").GetInt32(), d.GetProperty("mode").GetString()!)
            : null;

    private static void AssertPlan(JsonElement expected, RemediationPlan plan)
    {
        Assert.Equal(expected.GetProperty("mode").GetString(), plan.Mode);
        Assert.Equal(expected.GetProperty("steps").GetString(), plan.Steps);
        Assert.Equal(Str(expected, "fallback"), plan.Fallback);
        Assert.Equal(expected.GetProperty("grace_seconds").GetInt32(), plan.GraceSeconds);
        Assert.Equal(expected.GetProperty("source").GetString(), plan.Source);
    }

    private static ExecutorKeyRecord? Key(JsonElement v)
    {
        if (!v.TryGetProperty("key", out var k) || k.ValueKind != JsonValueKind.Object) return null;
        return new ExecutorKeyRecord
        {
            KeyId = k.GetProperty("key_id").GetString()!,
            PublicKey = k.GetProperty("public_key").GetString()!,
            ExecutorSovereignId = k.GetProperty("executor_sovereign_id").GetString()!,
            Role = Str(k, "role"),
            ResourcePrefix = Str(k, "resource_prefix"),
            RetiredAt = k.TryGetProperty("retired", out var r) && r.ValueKind == JsonValueKind.True ? "2026-01-01T00:00:00Z" : null,
        };
    }

    [Theory]
    [MemberData(nameof(VectorIds))]
    public void ReproducesTheReferenceOutcome(string id)
    {
        var v = Vector(id);
        var expected = v.GetProperty("expected");
        var input = v.TryGetProperty("input", out var i) ? i : default;
        switch (v.GetProperty("kind").GetString())
        {
            case "policy_canonical":
                {
                    var record = v.GetProperty("record").GetRawText();
                    using var doc = JsonDocument.Parse(record);
                    Assert.Equal(expected.GetProperty("canonical").GetString(),
                        Canonical.Of(doc.RootElement, ["signature"], OfflineVerifier.PolicyOmittedWhenAbsent));
                    Assert.Equal(expected.GetProperty("digest").GetString(), OfflineVerifier.PolicyDigest(record));
                    break;
                }
            case "policy_validation":
                Assert.Equal(expected.GetProperty("codes").EnumerateArray().Select(c => c.GetString()!),
                    RemediationRules.PolicySectionIssues(v.GetProperty("record").Deserialize<BoundaryPolicy>()!)
                        .Select(x => x.Code).Distinct().Order(StringComparer.Ordinal));
                break;
            case "remediation_plan":
                {
                    var plan = RemediationRules.Plan(input.GetProperty("verdict").GetString()!, Policies(input),
                        input.GetProperty("gate_evaluations").Deserialize<List<PolicyGateEvaluation>>()!,
                        new ChangeFacts(input.GetProperty("action").GetString()!, Str(input, "version_id"), input.GetProperty("rotatable").GetBoolean()),
                        Defaults(input));
                    AssertPlan(expected, plan);
                    Assert.Equal(expected.GetProperty("remediation_due_at").GetString(),
                        RemediationRules.DueAt(input.GetProperty("judged_at").GetString()!, plan.GraceSeconds));
                    break;
                }
            case "due_time":
                Assert.Equal(expected.GetProperty("remediation_due_at").GetString(), v.GetProperty("rule").GetString() == "review_denial"
                    ? RemediationRules.DueAfterDenial(Str(input, "current_due"), input.GetProperty("decided_at").GetString()!, input.GetProperty("grace_seconds").GetInt32())
                    : RemediationRules.DueAfterWaiver(input.GetProperty("waived_until").GetString()!, input.GetProperty("grace_seconds").GetInt32()));
                break;
            case "transition":
                {
                    var t = RemediationRules.NextState(input.GetProperty("state").GetString()!, input.GetProperty("event").GetString()!,
                        input.GetProperty("review_pending").GetBoolean());
                    Assert.Equal(Str(expected, "state"), t.State);
                    Assert.Equal(Str(expected, "refused"), t.Refusal);
                    Assert.Equal(t.State is not null, t.Allowed);
                    break;
                }
            case "decision_plan":
                {
                    var executed = input.GetProperty("executed");
                    AssertPlan(expected, RemediationRules.DecisionPlan(Policies(input),
                        executed.ValueKind == JsonValueKind.Null
                            ? null
                            : new ChangeFacts(executed[0].GetString()!, executed[1].ValueKind == JsonValueKind.Null ? null : executed[1].GetString(), executed[2].GetBoolean()),
                        Defaults(input)));
                    break;
                }
            case "rfc3339":
                {
                    var utc = RemediationRules.Rfc3339(input.ValueKind == JsonValueKind.String ? input.GetString() : null);
                    Assert.Equal(expected.GetProperty("valid").GetBoolean(), utc is not null);
                    Assert.Equal(Str(expected, "utc"), utc);
                    break;
                }
            case "emergency_map":
                Assert.Equal(expected.GetProperty("map").EnumerateObject().Select(p => (p.Name, p.Value.GetString()!)).OrderBy(p => p.Name, StringComparer.Ordinal),
                    RemediationRules.EmergencyMap(Policies(input), input.GetProperty("at").GetString()!)
                        .Select(p => (p.Key, p.Value)).OrderBy(p => p.Key, StringComparer.Ordinal));
                break;
            case "review_request":
                Assert.Equal(Str(expected, "code"), RemediationRules.ReviewRequestProblem(input.GetProperty("requested_by").GetString()!,
                    input.GetProperty("requester_holder").GetString()!, Str(input, "actor"), Str(input, "actor_holder"))?.Code);
                break;
            case "canonical_form":
                {
                    var record = v.GetProperty("record").GetRawText();
                    Assert.Equal(expected.GetProperty("canonical").GetString(), OfflineVerifier.OutOfBandCanonical(record));
                    Assert.Equal(expected.GetProperty("digest").GetString(), OfflineVerifier.OutOfBandDigest(record));
                    break;
                }
            case "verify_record":
                {
                    var record = v.GetProperty("record").GetRawText();
                    string[] keys = [v.GetProperty("public_key").GetString()!];
                    Assert.Equal(expected.GetProperty("valid").GetBoolean(), v.GetProperty("model").GetString() == "RemediationRecord"
                        ? OfflineVerifier.VerifyRemediationRecord(record, keys)
                        : OfflineVerifier.VerifyReviewRecord(record, keys));
                    break;
                }
            case "remediation_check":
                // The NA's order: the record's exact form first, then its signature, key and guard.
                Assert.Equal(Str(expected, "code"), RemediationRules.RecordProblem(v.GetProperty("record").GetRawText(), Key(v))?.Code);
                break;
            case "steps_problem":
                {
                    var plan = v.GetProperty("plan");
                    Assert.Equal(expected.GetProperty("consistent").GetBoolean(), RemediationRules.StepsProblem(plan.GetProperty("mode").GetString()!,
                        plan.GetProperty("steps").GetString()!, v.GetProperty("record").Deserialize<RemediationRecord>()!) is null);
                    break;
                }
            case "admin_approval":
                Assert.Equal(expected.GetProperty("valid").GetBoolean(),
                    RemediationRules.AdminApprovalValid(v.GetProperty("approval").Deserialize<AdminApproval>()!));
                break;
            case "review_approval":
                Assert.Equal(expected.GetProperty("valid").GetBoolean(), RemediationRules.ReviewApprovalProblem(
                    v.GetProperty("record").Deserialize<ReviewRecord>()!,
                    v.GetProperty("audiences").EnumerateArray().Select(a => a.GetString()!).ToList()) is null);
                break;
            case "review_holders":
                Assert.Equal(Str(expected, "code"), RemediationRules.ReviewHolderProblem(new ReviewRecord
                {
                    DecidedBy = input.GetProperty("decided_by").GetString()!,
                    DeciderHolder = input.GetProperty("decider_holder").GetString()!,
                    RequestedBy = Str(input, "requested_by"),
                    RequesterHolder = Str(input, "requester_holder"),
                    Actor = Str(input, "actor"),
                    ActorHolder = Str(input, "actor_holder"),
                })?.Code);
                break;
            case "verify_export":
                OutOfBandTests.VerifiesTheExport(input, expected);
                break;
            default:
                throw new InvalidOperationException($"unknown vector kind {v.GetProperty("kind").GetString()}");
        }
    }

    // ── Remediation records, signed as the reference signs them ────────────

    private static readonly DateTimeOffset At = new(2026, 1, 1, 0, 5, 0, TimeSpan.Zero);

    private static ExecutionRecorder Recorder(string sovereign = "sovereign-b") => new(sovereign, new SeedSigner(TestHelpers.ZeroSeedB64, "executor-b"));

    private static RemediationInput Rotation(Action<Dictionary<string, object?>>? change = null)
    {
        var fields = new Dictionary<string, object?>
        {
            ["RemediationId"] = "00000000-0000-4000-8000-000000000041",
            ["Steps"] = RemediationSteps.RotateForwardThenDisable,
            ["RotationEvidenceId"] = "00000000-0000-4000-8000-000000000031",
            ["VersionId"] = "v3",
            ["DisabledVersionId"] = "v2",
            ["Detail"] = null,
            ["Outcome"] = null,
        };
        change?.Invoke(fields);
        return new RemediationInput
        {
            RemediationId = (string?)fields["RemediationId"],
            SubjectKind = RemediationSubjectKinds.Judgement,
            SubjectId = "00000000-0000-4000-8000-000000000021",
            ChangeKind = ChangeKinds.Observation,
            ChangeId = "00000000-0000-4000-8000-000000000011",
            ResourceId = "kv:vault/api-key",
            Steps = (string)fields["Steps"]!,
            Outcome = (string?)fields["Outcome"],
            RotationEvidenceId = (string?)fields["RotationEvidenceId"],
            VersionId = (string?)fields["VersionId"],
            DisabledVersionId = (string?)fields["DisabledVersionId"],
            RemediatedAt = At,
            Detail = (string?)fields["Detail"],
        };
    }

    private static string Json(object record) => JsonSerializer.Serialize(record, Auth.SerializerOptions);

    [Fact]
    public async Task ARemediationIsSignedInTheReferencesForm()
    {
        var record = await Recorder().SignRemediation(Rotation());
        var written = Json(record);
        // The reference's record of the same remediation has the same signed form.
        Assert.Equal(Vector("canonical-remediation").GetProperty("expected").GetProperty("canonical").GetString(), OfflineVerifier.OutOfBandCanonical(written));
        Assert.Equal(RemediationOutcomes.Cancelled, record.Outcome);
        Assert.Equal("executor-b", record.Signature.GetProperty("key_id").GetString());
        Assert.True(OfflineVerifier.VerifyRemediationRecord(written, [ZeroKey]));
        Assert.True(OfflineVerifier.VerifyOutOfBandRecord(written, [ZeroKey]));
        var key = new ExecutorKeyRecord { KeyId = "executor-b", PublicKey = ZeroKey, ExecutorSovereignId = "sovereign-b", Role = "executor" };
        Assert.Null(RemediationRules.RecordProblem(written, key));
        Assert.Null(RemediationRules.Check(record, key));
        Assert.Null(RemediationRules.FormProblem(written));
    }

    [Fact]
    public async Task AnAlertChangesNothingAndDefaultsItsOutcome()
    {
        var record = await Recorder().SignRemediation(Rotation(f =>
        {
            f["Steps"] = RemediationSteps.None;
            f["RotationEvidenceId"] = f["VersionId"] = f["DisabledVersionId"] = null;
            f["RemediationId"] = null;
        }));
        Assert.Equal(RemediationOutcomes.Alerted, record.Outcome);
        Assert.True(Guid.TryParse(record.RemediationId, out _));
        Assert.Equal("2026-01-01T00:05:00Z", record.RemediatedAt);
        Assert.True(OfflineVerifier.VerifyRemediationRecord(Json(record), [ZeroKey]));
        Assert.Null(RemediationRules.StepsProblem(RemediationModes.AlertOnly, RemediationSteps.None, record));
    }

    [Theory]
    [InlineData("alerted-with-steps", "an alerted remediation changes nothing (steps none); a cancelled one does")]
    [InlineData("rotation-without-evidence", "a forward rotation names its evidence, the version it issued and the one disabled")]
    [InlineData("rotation-same-version", "the forward rotation issues another version than the one disabled")]
    [InlineData("disable-with-new-version", "only a forward rotation names rotation evidence or a new version")]
    [InlineData("detail-too-long", "the record does not match the RemediationRecord model (a field missing, empty, too long or of another type)")]
    [InlineData("alert-disables", "an alerted remediation disables nothing")]
    [InlineData("empty-subject", "the record does not match the RemediationRecord model (a field missing, empty, too long or of another type)")]
    public async Task AMalformedRemediationIsRefusedBeforeItIsSigned(string change, string detail)
    {
        var input = change switch
        {
            "alerted-with-steps" => Rotation(f => f["Outcome"] = RemediationOutcomes.Alerted),
            "rotation-without-evidence" => Rotation(f => f["RotationEvidenceId"] = null),
            "rotation-same-version" => Rotation(f => f["DisabledVersionId"] = "v3"),
            "disable-with-new-version" => Rotation(f => { f["Steps"] = RemediationSteps.Disable; f["RotationEvidenceId"] = null; }),
            "detail-too-long" => Rotation(f => f["Detail"] = new string('é', 1025)),
            "alert-disables" => Rotation(f => { f["Steps"] = RemediationSteps.None; f["RotationEvidenceId"] = f["VersionId"] = null; }),
            _ => new RemediationInput { SubjectKind = "judgement", ChangeKind = "observation", ChangeId = "c", ResourceId = "r", Steps = "disable" },
        };
        var e = await Assert.ThrowsAsync<OutOfBandRecordException>(() => Recorder().SignRemediation(input));
        Assert.Equal("remediation_malformed", e.Code);
        Assert.Equal(detail, e.Detail);
    }

    [Fact]
    public async Task ADetailOf1024CharactersIsSigned()
    {
        var record = await Recorder().SignRemediation(Rotation(f => f["Detail"] = new string('é', 1024)));
        Assert.True(OfflineVerifier.VerifyRemediationRecord(Json(record), [ZeroKey]));
    }

    [Fact]
    public async Task SecretMaterialIsRefusedBeforeItIsSigned()
    {
        var e = await Assert.ThrowsAsync<OutOfBandRecordException>(() =>
            Recorder().SignRemediation(Rotation(f => f["Detail"] = "rotated; the old value was -----BEGIN PRIVATE KEY-----")));
        Assert.Equal("remediation_secret_material", e.Code);
        Assert.Equal(e.Detail, RemediationRules.SecretProblem(new RemediationRecord { Detail = "rotated; the old value was -----BEGIN PRIVATE KEY-----" }));
    }

    [Fact]
    public async Task AValueTheNACouldNotReadIsRefused() =>
        await Assert.ThrowsAsync<StrictJsonException>(() => Recorder().SignRemediation(Rotation(f => f["Detail"] = "\ud800")));

    [Fact]
    public async Task TheChecksFollowTheNAsOrder()
    {
        var record = await Recorder().SignRemediation(Rotation());
        var written = Json(record);
        ExecutorKeyRecord Key(string? prefix = null, string? role = "executor", string? retired = null, string sovereign = "sovereign-b") =>
            new() { KeyId = "executor-b", PublicKey = ZeroKey, ExecutorSovereignId = sovereign, Role = role, ResourcePrefix = prefix, RetiredAt = retired };
        Assert.Equal("remediation_unknown_key", RemediationRules.RecordProblem(written, null)?.Code);
        Assert.Equal("remediation_unknown_key", RemediationRules.RecordProblem(written, Key(sovereign: "sovereign-a"))?.Code);
        Assert.Equal("remediation_key_retired", RemediationRules.RecordProblem(written, Key(retired: "2026-01-01T00:00:00Z", role: "observer"))?.Code);
        Assert.Equal(new RemediationProblem("remediation_out_of_scope", "signing key is an observer key, not an executor key"),
            RemediationRules.RecordProblem(written, Key(role: "observer")));
        Assert.Null(RemediationRules.RecordProblem(written, Key(role: null)));
        Assert.Null(RemediationRules.RecordProblem(written, Key(prefix: "kv:vault/")));
        Assert.Equal(new RemediationProblem("remediation_out_of_scope", "signing key covers only resources starting with kv:other/"),
            RemediationRules.RecordProblem(written, Key(prefix: "kv:other/")));
        var other = Key();
        other.PublicKey = Vector("check-accepted").GetProperty("key").GetProperty("public_key").GetString()!;
        Assert.Equal(new RemediationProblem("remediation_invalid_signature", "signature does not verify"), RemediationRules.RecordProblem(written, other));
        record.Signature = default;
        Assert.Equal(new RemediationProblem("remediation_invalid_signature", "record is not signed"), RemediationRules.Check(record, Key()));
        // The form is checked first, whatever the key.
        var withNull = JsonNode.Parse(written)!.AsObject();
        withNull["detail"] = null;
        Assert.Equal(new RemediationProblem("remediation_malformed", "record is not in its exact serialized form"),
            RemediationRules.RecordProblem(withNull.ToJsonString(), null));
    }

