    [Fact]
    public void AStepsMismatchNamesThePlanAndTheRecord()
    {
        var rotated = new RemediationRecord { Outcome = RemediationOutcomes.Cancelled, Steps = RemediationSteps.RotateForwardThenDisable };
        var alerted = new RemediationRecord { Outcome = RemediationOutcomes.Alerted, Steps = RemediationSteps.None };
        var deleted = new RemediationRecord { Outcome = RemediationOutcomes.Cancelled, Steps = RemediationSteps.Delete };
        Assert.Equal("the remediation is alert_only; the record says cancelled (rotate_forward_then_disable)",
            RemediationRules.StepsProblem(RemediationModes.AlertOnly, RemediationSteps.None, rotated));
        Assert.Equal("the remediation is a cancel (disable); the record only alerted", RemediationRules.StepsProblem(RemediationModes.Cancel, RemediationSteps.Disable, alerted));
        Assert.Null(RemediationRules.StepsProblem(RemediationModes.Cancel, RemediationSteps.Disable, deleted));
        Assert.Equal("the remediation is rotate_forward_then_disable; the record says delete",
            RemediationRules.StepsProblem(RemediationModes.Cancel, RemediationSteps.RotateForwardThenDisable, deleted));
    }

    // ── Typed records keep their signed form ───────────────────────────────

    public static TheoryData<string> SignedRecords() =>
        ["canonical-remediation", "canonical-review", "canonical-remediation-alerted", "signature-remediation-executor-key", "signature-review-na-key"];

    [Theory]
    [MemberData(nameof(SignedRecords))]
    public void ATypedRecordWrittenBackKeepsItsSignedForm(string id)
    {
        var v = Vector(id);
        var record = v.GetProperty("record").GetRawText();
        var model = v.GetProperty("model").GetString();
        var written = model == "RemediationRecord"
            ? Json(JsonSerializer.Deserialize<RemediationRecord>(record)!)
            : Json(JsonSerializer.Deserialize<ReviewRecord>(record)!);
        Assert.Equal(OfflineVerifier.OutOfBandCanonical(record), OfflineVerifier.OutOfBandCanonical(written));
        Assert.Equal(Canonical.FromJson(record), Canonical.FromJson(written));
    }

    [Fact]
    public void EachVerifierTakesItsOwnKindOnly()
    {
        var remediation = Vector("signature-remediation-executor-key");
        var review = Vector("signature-review-na-key");
        string[] executor = [remediation.GetProperty("public_key").GetString()!];
        string[] na = [review.GetProperty("public_key").GetString()!];
        Assert.True(OfflineVerifier.VerifyRemediationRecord(remediation.GetProperty("record").GetRawText(), executor));
        Assert.True(OfflineVerifier.VerifyReviewRecord(review.GetProperty("record").GetRawText(), na));
        Assert.False(OfflineVerifier.VerifyReviewRecord(remediation.GetProperty("record").GetRawText(), executor));
        Assert.False(OfflineVerifier.VerifyRemediationRecord(review.GetProperty("record").GetRawText(), na));
        Assert.True(OfflineVerifier.VerifyOutOfBandRecord(review.GetProperty("record").GetRawText(), na));
        Assert.False(OfflineVerifier.VerifyRemediationRecord("[]", executor));
        Assert.False(OfflineVerifier.VerifyReviewRecord("{}", na));
    }

    [Fact]
    public void AReviewIsVerifiedUnderTheKeyValidWhenItWasDecided()
    {
        var review = Vector("signature-review-na-key");
        var json = review.GetProperty("record").GetRawText();
        var key = review.GetProperty("public_key").GetString()!;
        var decided = OfflineVerifier.ParseTimestamp(review.GetProperty("record").GetProperty("decided_at").GetString()!);
        var valid = NAKeyHistory.ValidAlways([key]);
        Assert.True(OfflineVerifier.VerifyReviewRecord(json, valid));
        // A key valid from after the decision did not sign it.
        var before = new NAKeyHistory("na", null, [new NAKey(1, "na-key", key, decided.AddSeconds(1), null, null, false)]);
        Assert.False(OfflineVerifier.VerifyReviewRecord(json, before));
        Assert.True(OfflineVerifier.VerifyOutOfBandRecord(json, valid));
        Assert.False(OfflineVerifier.VerifyOutOfBandRecord(json, before));
    }

    // ── The state table ────────────────────────────────────────────────────

    [Theory]
    [InlineData("judged_allowed", "uphold", false, "review_not_pending")]
    [InlineData("judged_allowed", "open_review", true, "review_already_pending")]
    [InlineData("remediated", "open_review", false, "review_after_remediation")]
    [InlineData("remediated", "waive", true, "review_waiver_after_remediation")]
    [InlineData("remediated", "record_remediation", false, "remediation_already_recorded")]
    [InlineData("judged_allowed", "record_remediation", false, "remediation_not_due")]
    [InlineData("matched", "arm", false, "illegal_transition")]
    [InlineData("no_such_state", "arm", false, "illegal_transition")]
    public void ARefusedTransitionHasTheNAsCode(string state, string @event, bool reviewPending, string refusal)
    {
        var t = RemediationRules.NextState(state, @event, reviewPending);
        Assert.False(t.Allowed);
        Assert.Null(t.State);
        Assert.Equal(refusal, t.Refusal);
        Assert.NotEmpty(t.Detail);
    }

    [Fact]
    public void ARemediatedChangeStillHasItsPendingReviewDecided()
    {
        // Not review_already_pending: a remediated change takes no review, pending or not.
        Assert.Equal("review_after_remediation", RemediationRules.NextState(RemediationStates.Remediated, RemediationEvents.OpenReview, true).Refusal);
        Assert.Equal(RemediationStates.Remediated, RemediationRules.NextState(RemediationStates.Remediated, RemediationEvents.Deny, true).State);
        Assert.Equal(new RemediationTransition(RemediationStates.Upheld, null, ""), RemediationRules.NextState(RemediationStates.Waived, RemediationEvents.Uphold, true));
    }

