    [Fact]
    public void TheStateListsAreTheNAs()
    {
        Assert.Equal(["judged_allowed", "matched", "recorded"], RemediationStates.Standing);
        Assert.Equal(["remediation_due", "overdue", "waived"], RemediationStates.Open);
        Assert.Equal(["judged_allowed", "matched", "recorded", "remediation_due", "overdue", "remediated", "upheld", "waived"], RemediationStates.Kept);
    }

