    [Fact]
    public void ATimeThatIsNoneIsRefused()
    {
        Assert.Throws<ArgumentException>(() => RemediationRules.DueAt("yesterday", 60));
        Assert.Throws<ArgumentException>(() => RemediationRules.DueAfterDenial("soon", "2026-01-01T00:00:00Z", 60));
        Assert.Throws<ArgumentException>(() => RemediationRules.DueAfterWaiver("2026-01-01", 60));
        Assert.Throws<ArgumentException>(() => RemediationRules.DueAt("9999-12-31T23:59:59Z", 60));
        Assert.Equal("2026-01-01T00:01:00.500000Z", RemediationRules.DueAt("2026-01-01T01:00:00.5+01:00", 60));
        // A finer fraction is cut to microseconds, as the reference reads it.
        Assert.Equal("2026-01-01T00:01:00.123456Z", RemediationRules.DueAt("2026-01-01T00:00:00.1234567Z", 60));
        Assert.Equal("2026-01-01T00:01:00Z", RemediationRules.DueAfterWaiver("2026-01-01T00:00:00.0000009Z", 60));
        Assert.Throws<ArgumentException>(() => RemediationRules.DueAt("2026-01-01T00:00.1234567Z", 60));
    }

    [Fact]
