        Assert.Equal("0001-01-01T00:00:00Z", RemediationRules.Rfc3339("0001-01-01T00:01:00+00:01"));
        Assert.Null(RemediationRules.Rfc3339(null));
        Assert.Null(RemediationRules.Rfc3339("2026-10-12T09:00:00Z\n"));
    }

